   418	/**
   419	 * @brief 无动画关闭的安全实现
   420	 *
   421	 * 使用场景：
   422	 *   - 需要快速返回，不需要关闭动画
   423	 *   - 某些页面不支持动画
   424	 *   - 用户按下返回键快速返回
   425	 *
   426	 * 保证的安全顺序（与打开过程对称）：
   427	 *   1. will_disappear_cb - 页面即将隐藏
   428	 *   2. 隐藏 UI（无动画）
   429	 *   3. 暂停定时器
   430	 *   4. dis_disappear_cb - 页面已隐藏
   431	 *   5. close_cb - 清理资源
   432	 *   6. 删除页面对象
   433	 *
   434	 * ✓ 避免直接调用回调的危险
   435	 * ✓ 保证执行顺序的正确性
   436	 * ✓ 即使没有动画也是安全的
   437	 */
   438	static void _close_page_without_animation(lv_pm_page_t page)
   439	{
   440	    if (page == NULL) {
   441	        LV_LOG_ERROR("[PAGE_MANAGER] [NO_ANIMA] 尝试关闭空页面");
   442	        return;
   443	    }
   444	
   445	    LV_LOG_INFO("[PAGE_MANAGER] [NO_ANIMA] 开始关闭页面（无动画）: ID=%d, Name=%s",
   446	           page->id, page->name);
   447	
   448	    page->flag.is_back = 1;
   449	
   450	    // Step 1: will_disappear - 在隐藏前通知
   451	    if (page->will_disappear_cb) {
   452	        LV_LOG_INFO("[PAGE_MANAGER] [NO_ANIMA] 执行 will_disappear_cb: ID=%d",
   453	               page->id);
   454	        page->will_disappear_cb(page);
   455	    }
   456	
   457	    // Step 2: 隐藏 UI（无动画）
   458	    if (page->page != NULL) {
   459	        lv_obj_add_flag(page->page, LV_OBJ_FLAG_HIDDEN);
   460	        lv_obj_clear_flag(page->page, LV_OBJ_FLAG_CLICKABLE);
   461	        LV_LOG_INFO("[PAGE_MANAGER] [NO_ANIMA] UI 已隐藏: ID=%d", page->id);
   462	    }
   463	
   464	    // Step 3: 暂停定时器
   465	    if (page->page_timer != NULL && page->flag.timer_backend_run == 0) {
   466	        lv_timer_pause(page->page_timer);
   467	        LV_LOG_INFO("[PAGE_MANAGER] [NO_ANIMA] 定时器已暂停: ID=%d", page->id);
   468	    }
   469	
   470	    // Step 4: dis_disappear - 页面已隐藏（即使没有动画也视为完成）
   471	    if (page->dis_disappear_cb) {
   472	        LV_LOG_INFO("[PAGE_MANAGER] [NO_ANIMA] 执行 dis_disappear_cb: ID=%d",
   473	               page->id);
   474	        page->dis_disappear_cb(page);
   475	    }
   476	
   477	    // Step 5: close - 清理资源（最关键的步骤，必须在删除前调用）
   478	    if (page->close_cb) {
   479	        LV_LOG_INFO("[PAGE_MANAGER] [NO_ANIMA] 执行 close_cb: ID=%d", page->id);
   480	        page->close_cb(page);
   481	    }
   482	
   483	    _pm_msg_clear(page);
   484	
   485	    LV_LOG_INFO("[PAGE_MANAGER] [NO_ANIMA] 页面关闭完成（无动画）: ID=%d", page->id);
   486	}
