   506	/**
   507	 * @brief 处理 LV_PM_TARGET_RESET 模式
   508	 * @param open_page 要打开的页面
   509	 */
   510	static void _handle_target_reset(lv_pm_page_t open_page)
   511	{
   512	    LV_LOG_INFO("[OPEN_TARGET] RESET 模式开始");
   513	    LV_LOG_INFO("[OPEN_TARGET] 当前路由表大小: %d", g_pm_history_count);
   514	
   515	    int pages_to_delete = g_pm_history_count;
   516	
   517	    /* 逆序删除所有页面 */
   518	    for (int i = pages_to_delete - 1; i >= 0; i--) {
   519	        lv_pm_id delete_id = g_pm_history[i];
   520	        lv_pm_page_t delete_page = _get_page_by_id(delete_id);
   521	
   522	        if (delete_page != NULL) {
   523	            LV_LOG_INFO("[OPEN_TARGET] 删除页面: ID=%d, Name=%s", delete_page->id, delete_page->name);
   524	
   525	            if (delete_page->dis_disappear_cb) {
   526	                delete_page->dis_disappear_cb(delete_page);
   527	            }
   528	            if (delete_page->close_cb) {
   529	                delete_page->close_cb(delete_page);
   530	            }
   531	
   532	            _pm_msg_clear(delete_page);
   533	            lv_pm_delete_deep_page(delete_id);
   534	        }
   535	
   536	        g_pm_history_count--;
   537	        g_pm_history[g_pm_history_count] = 0;
   538	    }
   539	
   540	    /* 添加新页面 */
   541	    g_pm_history[0] = open_page->id;
   542	    g_pm_history_count = 1;
   543	
   544	    LV_LOG_INFO("[OPEN_TARGET] RESET 完成: ID=%d, Name=%s, 路由表大小=%d",
   545	           open_page->id, open_page->name, g_pm_history_count);
   546	}
